using System;using System.Threading.Tasks;namespace AshkanSocial.Core.Services{
public sealed class LocalRealtimeClient:IRealtimeClient{
 public RealtimeConnectionState State{get;private set;}=RealtimeConnectionState.Disconnected;public event Action<RealtimeConnectionState> StateChanged;public event Action<string,string,string> DirectMessageReceived;public event Action<string,string,bool> TypingChanged;public event Action<string,bool> PresenceChanged;public event Action<string,string,string> GroupMessageReceived;public event Action<string> NotificationReceived;
 void Set(RealtimeConnectionState s){State=s;StateChanged?.Invoke(s);}public Task ConnectAsync(string userId){Set(RealtimeConnectionState.Connected);PresenceChanged?.Invoke(userId,true);return Task.CompletedTask;}public Task DisconnectAsync(){Set(RealtimeConnectionState.Disconnected);return Task.CompletedTask;}public Task SendDirectMessageAsync(string id,string from,string to,string text){DirectMessageReceived?.Invoke(from,to,text);return Task.CompletedTask;}public Task SendTypingAsync(string from,string to,bool typing){TypingChanged?.Invoke(from,to,typing);return Task.CompletedTask;}public Task SendGroupMessageAsync(string id,string groupId,string from,string text){GroupMessageReceived?.Invoke(groupId,from,text);return Task.CompletedTask;}public Task JoinGroupAsync(string groupId){return Task.CompletedTask;}public void RaiseNotification(string text){NotificationReceived?.Invoke(text);}public void Dispose(){}}
}